#pragma once
int runWaveformVisualChecks(){
 auto make=[](double hz,int frames=44100){auto b=std::make_shared<juce::AudioBuffer<float>>(2,frames);for(int n=0;n<frames;++n)for(int ch=0;ch<2;++ch)b->setSample(ch,n,(float)(.6*std::sin(n*hz*juce::MathConstants<double>::twoPi/44100)));return b;};
 for(auto pair:{std::make_pair(60.,0),std::make_pair(900.,1),std::make_pair(8000.,2)}){auto tone=make(pair.first);auto original=*tone;FrequencyWaveform display;auto start=juce::Time::getMillisecondCounterHiRes();if(!display.build(*tone,44100))return 1860;auto peak=display.range(4096,40000);auto c=peak.colour();std::array<int,3> rgb{c.getRed(),c.getGreen(),c.getBlue()};if(!peak.present||rgb[pair.second]<=rgb[(pair.second+1)%3]||rgb[pair.second]<=rgb[(pair.second+2)%3]||std::abs(peak.low+.6f)>.001||std::abs(peak.high-.6f)>.001)return 1861;for(int n=0;n<tone->getNumSamples();++n)if(original.getSample(0,n)!=tone->getSample(0,n))return 1862;std::cout<<"Frequency "<<pair.first<<" Hz mapped to band "<<pair.second<<" in "<<juce::Time::getMillisecondCounterHiRes()-start<<" ms\n";}
 auto tone=make(60,4096);FrequencyWaveform full,left,right;full.build(*tone,44100);juce::AudioBuffer<float> a(2,2048),b(2,2048);for(int ch=0;ch<2;++ch){a.copyFrom(ch,0,*tone,ch,0,2048);b.copyFrom(ch,0,*tone,ch,2048,2048);}left.build(a,44100);right.build(b,44100,0,2,0,-1,left.tail);auto expected=full.range(0,4096),combined=left.range(0,2048);combined.merge(right.range(0,2048));for(int i=0;i<3;++i)if(std::abs(expected.energy[i]-combined.energy[i])>juce::jmax(.001f,expected.energy[i]*1e-5f))return 1863;
 FrequencyWaveform limited;limited.build(*tone,44100,0,2,1024,2048);if(limited.range(0,1000).present||limited.range(2048,4096).present||!limited.range(1024,2048).present)return 1864;
 FrequencyWaveform cancelled;if(cancelled.build(*tone,44100,0,2,0,-1,{},[]{return true;}))return 1865;
 FrequencyWaveformWorker worker;auto first=make(60,441000),second=make(8000);worker.setSource(first,44100);worker.setSource(second,44100);bool done=false;for(int i=0;i<500;++i){auto ready=worker.result();if(ready&&ready->source==second){done=true;if(ready->waveform.range(4096,40000).colour().getBlue()<200)return 1866;break;}juce::Thread::sleep(2);}if(!done)return 1867;worker.setSource({},44100);if(worker.result())return 1868;
 TrackStemWorker::Window window;auto chunk=std::make_shared<TrackStemWorker::Chunk>();chunk->validEnd=2048;for(int stem=0;stem<4;++stem){for(int ch=0;ch<2;++ch)chunk->buffer.copyFrom(stem*2+ch,0,a,ch,0,2048);chunk->visuals[stem].build(chunk->buffer,44100,stem*2,2);}window.chunks.push_back(chunk);if(!window.waveform(3,0,2048).present||window.waveform(0,2048,4096).present)return 1869;
 std::cout<<"Colour summaries, stereo peaks, chunk filter continuity, unavailable regions, cancellation and source replacement passed\n";return 0;
}
int runTrackStemGui(const char* audioPath,const char* imagePath){
 juce::ScopedJuceInitialiser_GUI init;juce::AudioFormatManager formats;formats.registerBasicFormats();std::unique_ptr<juce::AudioFormatReader> reader(formats.createReaderFor(juce::File(audioPath)));if(!reader)return 1870;Processor p;auto audio=std::make_shared<AudioData>();audio->rate=reader->sampleRate;audio->buffer.setSize(2,(int)reader->lengthInSamples);if(!reader->read(&audio->buffer,0,audio->buffer.getNumSamples(),0,true,true))return 1871;audio->path=audioPath;audio->buildWaveformPeaks();p.audio=audio;p.split(1,false);p.setPlaybackMode(4);p.trackGridEdited=p.trackGridReady=true;p.trackGrid.bpm=120;p.trackGrid.anchors={{0,0},{(double)audio->buffer.getNumSamples()-1,(audio->buffer.getNumSamples()-1)/audio->rate*2}};p.setTrackLoop(true,8,24);p.trackPlayer.position=16;p.serviceTrack();Editor editor(p);editor.setSize(1360,1100);editor.resized();if(!editor.prepareTrackVisualsForCheck())return 1872;
 auto save=[&](juce::String path){juce::FileOutputStream out(juce::File{path});out.setPosition(0);out.truncate();juce::PNGImageFormat png;return png.writeImageToStream(editor.createComponentSnapshot(editor.getLocalBounds()),out);};
 if(!save(imagePath))return 1873;editor.toggleBrowserForCheck();editor.setSize(720,1000);if(!save(juce::String(imagePath)+"-small.png"))return 1874;
 auto begin=juce::Time::getMillisecondCounterHiRes();for(int i=0;i<30;++i)editor.createComponentSnapshot(editor.getLocalBounds());std::cout<<"Four-lane compact snapshot average "<<(juce::Time::getMillisecondCounterHiRes()-begin)/30<<" ms\n";
 p.trackStemsEnabled=false;p.serviceTrack();if(!editor.prepareTrackVisualsForCheck()){} // Model may be released; mix display stays available.
 editor.resized();return save(juce::String(imagePath)+"-mix.png")?0:1875;
}
